{
  "title": "Weekend Trip To-Do",
  "body": "<div class="wrap"><h2>Weekend trip planning</h2><div class="add"><input id="new" type="text" placeholder="Add a task…"><button id="add">Add</button></div><ul id="list"></ul><p id="count" class="count"></p></div>",
  "css": ".wrap{font-family:system-ui,sans-serif;max-width:420px;margin:0 auto;padding:16px}h2{margin:0 0 12px;font-size:20px}.add{display:flex;gap:8px;margin-bottom:12px}.add input{flex:1;padding:8px 10px;border:1px solid #bbb;border-radius:6px;font-size:14px}.add button{padding:8px 14px;border:0;border-radius:6px;background:#2f6fed;color:#fff;font-size:14px;cursor:pointer}ul{list-style:none;margin:0;padding:0}li{display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid #e1e1e1;border-radius:6px;margin-bottom:6px;background:#fafafa}li span{flex:1;font-size:14px}li.done span{text-decoration:line-through;color:#888}li button{border:0;background:transparent;color:#c0392b;font-size:16px;cursor:pointer}.count{margin-top:12px;font-size:13px;color:#555}.empty{color:#888;font-size:14px;padding:8px 0}",
  "scripts": [
    "if (!state.items) { state.items = [ {id: 1, text: 'Pick destination and dates', done: false}, {id: 2, text: 'Book accommodation', done: false}, {id: 3, text: 'Make a packing list', done: false} ]; state.nextId = 4; }
const list = root.querySelector('#list');
const count = root.querySelector('#count');
const input = root.querySelector('#new');
const addBtn = root.querySelector('#add');
const render = () => {
  list.replaceChildren();
  if (state.items.length === 0) {
    const p = root.create('li');
    p.classList.add('empty');
    p.textContent = 'Nothing to do. Add a task above.';
    list.append(p);
  }
  for (const item of state.items) {
    const li = root.create('li');
    if (item.done) { li.classList.add('done'); }
    const cb = root.create('input');
    cb.setAttribute('type', 'checkbox');
    cb.checked = item.done;
    cb.addEventListener('change', () => { item.done = !item.done; render(); });
    const span = root.create('span');
    span.textContent = item.text;
    const del = root.create('button');
    del.textContent = '✕';
    del.setAttribute('title', 'Delete');
    del.addEventListener('click', () => { state.items = state.items.filter(i => i.id !== item.id); render(); });
    li.append(cb);
    li.append(span);
    li.append(del);
    list.append(li);
  }
  const left = state.items.filter(i => !i.done).length;
  count.textContent = `${left} of ${state.items.length} left`;
};
if (!addBtn.getAttribute('data-bound')) {
  addBtn.setAttribute('data-bound', '1');
  addBtn.addEventListener('click', () => {
    const text = (input.value || '').trim();
    if (text) {
      state.items.push({ id: state.nextId, text: text, done: false });
      state.nextId = state.nextId + 1;
      input.value = '';
      render();
    }
  });
}
render();"
  ]
}
